(9454, 'frFR', 'Récupérer 500 graines draeniques.', 'Collectionneur de graines draeniques', 'Déblocage : jardin de simples, plan de niveau 3', 56647),
(9129, 'frFR', 'Faire progresser 20 sujets de fief jusqu\’au niveau 40.', 'Remplir les rangs', 'Déblocage : fortin nain/usine de guerre, plan de niveau 3', 56647),
(8643, 'frFR', 'Terminer une saison de JcJ dans les premiers 0,1% du classement d\’arène (nécessite 50 matchs gagnés pendant la saison 14).', 'Gladiateur dramatique : saison 14', 'Titre de personnage : gladiateur ou gladiatrice dramatique', 56647),
(1956, 'frFR', 'Lire les volumes de « Les écoles de magie des Arcanes » trouvés à Dalaran et listés ci-dessous.', 'Lectures studieuses', 'Jouet : les écoles de magie des Arcanes – Maîtrise', 56647),
(40642, 'frFR', 'Vaincre la monstruosité de pierre du Vide dans la colonie en mode mythique ou clé mythique.', 'La colonie : mode mythique', '', 56647),
(40637, 'frFR', 'Vaincre la monstruosité de pierre du Vide dans la colonie en mode héroïque ou supérieur.', 'La colonie : mode héroïque', '', 56647),
(40604, 'frFR', 'Vaincre Rasha\’nan dans le Brise-Aube en mode mythique ou clé mythique.', 'Le Brise-Aube : mode mythique', '', 56647),
(40601, 'frFR', 'Vaincre Rasha\’nan dans le Brise-Aube en mode héroïque ou supérieur.', 'Le Brise-Aube : mode héroïque', '', 56647),
(40599, 'frFR', 'Vaincre Rasha\’nan dans le Brise-Aube.', 'Le Brise-Aube', '', 56647),
(40596, 'frFR', 'Vaincre la prêtresse Murrapy au prieuré de la Flamme sacrée en mode mythique ou clé mythique.', 'Prieuré de la Flamme sacrée : mode mythique', '', 56647),
(40592, 'frFR', 'Vaincre la prêtresse Murrapy au prieuré de la Flamme sacrée en mode héroïque ou supérieur.', 'Prieuré de la Flamme sacrée : mode héroïque', '', 56647),
(40590, 'frFR', 'Vaincre la prêtresse Murrapy au prieuré de la Flamme sacrée.', 'Prieuré de la Flamme sacrée', '', 56647);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(775, 'frFR', 'Outil Raids : secrets du palais des Nérub\’ar', 'Sikran dirige les forces nérubiennes avec ruse et précision, éliminant tout intrus ou intruse qui voudrait usurper le trône de la reine.', 'Rejoindre un raid', '', '', 56647),
(743, 'frFR', 'L\’éveil de la machine', 'Rendez-vous à Gundargaz pour aider les mandataires des machines à éveiller les machines antiques.', '', '', '', 56647),
(760, 'frFR', 'La Cavepierre', 'Biergoth à Dornogal veut que vous éliminiez la corruption des Skardyns dans le donjon de la Cavepierre.', 'Accepter la quête', 'Si vous y parvenez, vous pourrez améliorer votre renom auprès de la faction de The War Within de votre choix !', '', 56647),
(696, 'frFR', 'Étincelles de vie : Rêve d\’émeraude', 'Jephyrn de Valdrakken vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(655, 'frFR', 'Étincelles de vie : grotte de Zaralek', 'Bram, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(637, 'frFR', 'Étincelles de vie : confins Interdits', 'Kazure, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(607, 'frFR', 'Étincelles de vie : Thaldraszus', 'Seknar, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(606, 'frFR', 'Étincelles de vie : travée d\’Azur', 'Keenu, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(605, 'frFR', 'Étincelles de vie : plaines d\’Ohn\’ahra', 'Ailith Pierrebrise, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(604, 'frFR', 'Étincelles de vie : rivages de l\’Éveil', 'Ailith Pierrebrise, de Valdrakken, vous met au défi de vaincre vos adversaires en combat JcJ.', 'Accepter la quête', '', '', 56647),
(738, 'frFR', 'Le Conflit intérieur', 'Rendez-vous en Silithus pour enquêter sur le mystère des visions qui se manifestent aux quatre coins d\’Azeroth.', 'Accepter la quête', '', '', 56647),
(737, 'frFR', 'Le Conflit intérieur', 'Rendez-vous en Silithus pour enquêter sur le mystère des visions qui se manifestent aux quatre coins d\’Azeroth.', 'Accepter la quête', '', '', 56647);
