INSERT INTO `battle_pet_ability_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2435, 'frFR', 'Embrasement de mana', 'Inflige [StandardDamage(1,1,2436)] |4point:points; de dégâts [School()] à chaque fois que votre mascotte subit des dégâts directs.\n\nDure [duration(1,1)] |4tour:tours;.', 56647),
(2378, 'frFR', 'Rayons lumineux', '|cffffffffChances de toucher :|r [StandardAccuracy(1,1)]\n\nInflige [StandardDamage(1,1)] |4point:points; de dégâts [School()] à la mascotte adverse active et [StandardDamage(1,2)] |4point:points; de dégâts [School()] aux mascottes adverses en retrait. Rend [StandardHealing(1,1)] |4point:points; de vie aux alliés.', 56647),
(1369, 'frFR', 'Aiguillonneur acéré', '[StandardAccuracy(1,1)] |cffffffffchances de toucher|r\n\nInflige instantanément [StandardDamage(1,1)] |4point:points; de dégâts [School()], et 20 % de chances d\’|cFF1EFF00empoisonner|r la cible en lui infligeant [StandardDamage(1,1,379)] |4point supplémentaire:points supplémentaires; de dégâts [School(379)] par tour pendant [duration(1,2)] |4tour:tours;.', 56647);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(3265, 'frFR', 'Indiscutablement le plus digne des musquards malodorants.', '|cFFFFD200Haut fait :|r Les petits ruisseaux font les grandes rivières', 56647),
(4517, 'frFR', 'Dans un miracle de rêves et de souhaits, Ciremèche s\’est réveillée et a dévalé la tête d\’un Kobold pour suivre sa propre voie.', '|cFFFFD200Haut fait :|r Safari de Khaz Algar|n', 56647),
(4581, 'frFR', '', '|cFFFFD200Haut fait : |rUn tour de champion : The War Within|n|cFFFFD200Catégorie : |rMonde', 56647),
(4543, 'frFR', 'La créature d\’ombre suit sir Finley Mrrgglton depuis qu\’il est tombé dessus dors de l\’une de ses expéditions. Finley s\’étant beaucoup attaché à cet ami ténébreux, il ne s\’en séparera pas facilement.', '|cFFFFD200Vendeur : |rsir Finley Mrrgglton|n|cFFFFD200Région : |rDornogal|n|cFFFFD200Coût : |r10 000|Hcurrency:2803|h|TInterface\\ICONS\\INV_Misc_ElvenCoins.blp:0|t|h', 56647);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(268268, 'frFR', '', 'Par la volonté de la Flamme, mais j\’en doute.', 56647),
(259733, 'frFR', '', 'À votre tour.', 56647),
(260378, 'frFR', '', 'Merci, père. Espérons que ça n\’arrivera pas trop vite.', 56647),
(260375, 'frFR', 'Quand je ne serai plus là, tu gouverneras avec une élégance et une force dont je n\’ai jamais pu rêver.', '', 56647),
(260374, 'frFR', 'Mais tu n\’as plus besoin de moi. Je suis heureux de voir que tu es devenue aussi forte.', '', 56647),
(260371, 'frFR', 'Je voulais juste te protéger, et là encore, j\’aurais pu faire mieux. Même maintenant, on est en danger.', '', 56647),
(260345, 'frFR', '', 'Je ne peux pas vraiment tout pardonner, mais au moins je comprends.', 56647),
(260336, 'frFR', '', 'Mais plus je vieillis, plus Dagran grandit et plus j\’en apprends sur les responsabilités…', 56647),
(260333, 'frFR', '', 'Je pourrais encore en rajouter sur ce que j\’ai subi quand j\’étais gamine, moi… et le père de Dagran.', 56647),
(260303, 'frFR', 'Malgré tout, tu as appris à gouverner avec brio et tu as su laisser Dagran choisir qui il veut devenir.', '', 56647),
(260294, 'frFR', 'Non, tu as raison. J\’ai fait des choses dont je ne suis pas fier.', '', 56647),
(260287, 'frFR', '', 'Vraiment ? Eh bien, si j\’avais cru entendre ça un jour… Il y a quelque chose qui ne va pas ?', 56647),
(260283, 'frFR', 'Je voulais juste te dire… que j\’étais fier de toi.', '', 56647),
(260266, 'frFR', 'Je vois ça. Tu t\’en sors mieux que moi avec ces… machines.', '', 56647),
(260265, 'frFR', '', 'Pas d\’inquiétude, père. J\’ai la situation en main.', 56647),
(260264, 'frFR', 'Moira, est-ce que je peux te parler ?', '', 56647),
(263779, 'frFR', 'Merci, maman. Je… j\’ai rien à dire d\’autre que… j\’ai hâte de voir ce qu\’on va découvrir… ensemble.', '', 56647),
(263778, 'frFR', '', 'Il n\’y a personne d\’autre avec qui je préférerais faire écraser une ville, faire des rencontres et sauter dans un trou noir.', 56647),
(263777, 'frFR', '', 'Tu es l\’avenir de notre peuple et tu as beaucoup à offrir au monde. Ne laisse personne te dire le contraire.', 56647),
(263776, 'frFR', '', 'Des heures ? Je t\’écouterais pendant des jours. Je ne suis peut-être pas impartiale puisque tu es mon fils, mais tu as un bel esprit.', 56647),
(263775, 'frFR', 'Ah oui ? Des fois, tu me poses des questions… et si je suis emballé, je peux parler pendant des heures.', '', 56647),
(263774, 'frFR', '', 'Tu as toujours eu un don pour l\’histoire et la culture. Je te vois déjà comme conseiller.', 56647),
(263773, 'frFR', '', 'Très bien. Je ne voulais pas t\’exposer au danger, mais contente de voir que l\’aventure te plaît.', 56647),
(263772, 'frFR', 'Non, maman. J\’ai tant appris ici. Le monde semble si nouveau… et si vieux à la fois.', '', 56647),
(263771, 'frFR', '', 'Dagran, prêt à descendre ? Ce n\’est pas la peine. Tu peux rester à l\’Archive si tu le souhaites.', 56647),
(260591, 'frFR', '', 'Dornogal a perdu un protecteur, et j\’ai perdu un ami.', 56647),
(260588, 'frFR', '', 'Si nous n\’avions pas été tous deux si bornés, je suis certaine que son sort aurait été différent.', 56647),
(260584, 'frFR', '', 'J\’ai cru qu\’il ne me pardonnerait jamais de l\’avoir abandonné, attelé à Dornogal, mais finalement…', 56647),
(260582, 'frFR', '', 'Mes conclusions m\’éloignaient des Titans, les siennes l\’en rapprochaient encore plus.', 56647),
(260580, 'frFR', '', 'J\’ai vu ce qui arrivait aux nôtres. Et Baelgrim l\’a vu aussi.', 56647),
(260579, 'frFR', '', 'Après, tout a commencé… à se dégrader. La galerie Primaire, l\’archive… Quand on a commencé à comprendre, le désespoir s\’est installé.', 56647),
(260578, 'frFR', '', 'Dornogal avait autant besoin de lui que de moi.', 56647),
(260576, 'frFR', '', 'Comme deux béliers dans le même attelage, lui à tirer avec ses freux et moi avec ma forge et ma carrière.', 56647),
(260573, 'frFR', '', 'Mutuellement, nous jugions nos réussites selon celles de l\’autre. Qui aurait le plus la faveur des Titans ?', 56647),
(260566, 'frFR', '', 'Baelgrim était un rival. Il est devenu garde en même temps que moi.', 56647),
(276521, 'frFR', 'Ouvrir un coffre lourd, un coffre abondant ou un trésor caché à la fin de n\’importe quel Gouffre vous fera progresser vers les récompenses que vous avez trouvées.\n\nPlus le Gouffre sera difficile, plus votre progression sera importante !', '', 56647),
(264632, 'frFR', '', 'Ha ha ! Ha ha ha !', 56647),
(263040, 'frFR', 'Cet arbre est magnifique ! Il était un peu décharné, mais dès que ce crabe est arrivé, ses feuilles ont retrouvé des couleurs. Très étrange !\n\nSi j\’avais d\’autres crabes comme ça, je pourrais peut-être lui redonner le moral. On dirait qu\’ils aiment les arbres !', 'Cet arbre est magnifique ! Il était un peu décharné, mais dès que ce crabe est arrivé, ses feuilles ont retrouvé des couleurs. Très étrange !\n\nSi j\’avais d\’autres crabes comme ça, je pourrais peut-être lui redonner le moral. On dirait qu\’ils aiment les arbres !', 56647),
(263507, 'frFR', 'ANOMALIE INDÉTERMINÉE DÉTECTÉE. LANCEMENT DU PROGRAMME DE PURGE DE L\’ÉVEIL.', '', 56647),
(258213, 'frFR', 'Empruntez ce portail jusqu\’à Khaz Algar. Celles et ceux qui ont pu s\’échapper ont besoin d\’aide.', '', 56647),
(266134, 'frFR', 'Compris, oncle Brann ! Est-ce que je dois le combattre ?', '', 56647),
(253394, 'frFR', 'Le duc Velhan a la situation bien en main, ça ne fait aucun doute. C\’est un excellent chef !\n\nC\’est grâce à lui que relativement peu d\’individus arathis ont péri à la Chute de Velhan.', 'Le duc Velhan a la situation bien en main, ça ne fait aucun doute. C\’est un excellent chef !\n\nC\’est grâce à lui que relativement peu d\’individus arathis ont péri à la Chute de Velhan.', 56647),
(268948, 'frFR', '', '<gloussement amusé>', 56647),
(268647, 'frFR', '', 'Les golems de guerre sont actifs, la production a repris.', 56647),
(265314, 'frFR', '', 'Installation réactivée !', 56647),
(265313, 'frFR', 'Emballez tout, les gars ! Je sais reconnaître une défaite…', '', 56647),
(265081, 'frFR', '', 'Si elle peut faire ça à un être sublimé…', 56647),
(265078, 'frFR', '', 'Elle a saisi l\’esprit d\’Y\’tekhi sans effort.', 56647),
(265077, 'frFR', '', 'Partons ! Vite !', 56647),
(263478, 'frFR', '', 'Est achevée.', 56647),
(263476, 'frFR', '', 'Votre Sublimation…', 56647),
(260586, 'frFR', '', 'Maintenant, Zed-Zed !', 56647),
(260581, 'frFR', '', 'Vous savez quoi ? C\’EST LE CAS.', 56647),
(260577, 'frFR', 'Vous auriez dû amener plus de gros bras.', '', 56647),
(261892, 'frFR', '', 'Nous avons beaucoup à faire.', 56647),
(261891, 'frFR', 'Et maintenant, Lufsela ?', '', 56647),
(261890, 'frFR', '', 'Ils ont choisi de nous aider de leur plein gré.', 56647),
(261889, 'frFR', '', 'Pas juste le mien. Le leur.', 56647),
(261888, 'frFR', 'Bravo. Ils ont entendu votre appel.', '', 56647),
(261884, 'frFR', 'Appelez-les et ils répondront.', '', 56647),
(261883, 'frFR', 'Lufsela, les freux lisent vos intentions. Concentrez-vous.', '', 56647),
(261881, 'frFR', 'S\’il a pu résister aux Titans, vous aussi !', '', 56647),
(261880, 'frFR', 'Baelgrim a invoqué les freux de la tempête seul.', '', 56647),
(261878, 'frFR', '', 'Je ne peux pas. Les Titans…', 56647),
(263833, 'frFR', '', '<Grognements>', 56647),
(261968, 'frFR', '… tous Déliés !', '', 56647),
(261967, 'frFR', 'Moi, conseiller de Dornogal, je déclare que nous sommes…', '', 56647),
(261966, 'frFR', 'Qui nous ferait l\’honneur de s\’en charger ?', '', 56647),
(261958, 'frFR', 'Là où ils ont été rédigés.', '', 56647),
(261957, 'frFR', 'Il convient donc de le faire ici, là où tout a commencé…', '', 56647),
(261956, 'frFR', '', 'Et pour cela, nous devons renoncer aux édits à jamais.', 56647),
(261955, 'frFR', '', 'Oui. Nous devons aider nos nouveaux alliés.', 56647),
(261954, 'frFR', 'Alors ? Nous avons un accord ?', '', 56647),
(252684, 'frFR', 'Hein ? Je vous connais ?\n\nNon ? Parfait. Ma mémoire va à vau-l\’eau.\n\nJe suis Korgran, l\’un des gardiens de la cime Éplorée, un endroit réservé aux êtres déliés qui approchent de leur dernière extinction.\n\nCes derniers viennent ici à leurs derniers instants afin de briser le cycle des titans et de rester fidèles à eux-mêmes dans les mémoires.\n\nÀ moins que votre race ne connaisse la même stase que nous, je ne sais pas ce que je peux faire pour vous.', '', 56647),
(261480, 'frFR', 'Tu as vu ces nouveaux tomes, oncle Brann ? Ils doivent venir de la bibliothèque de Drenden.', '', 56647),
(259252, 'frFR', 'Bien le bonjour ! Vous êtes ici pour discuter avec oncle Brann ?', '', 56647),
(251198, 'frFR', 'Je vous suis, tous les deux. J\’ai hâte d\’en apprendre plus sur tout cet endroit !', '', 56647),
(261676, 'frFR', '', 'Salutations. Il me tarde de découvrir Khaz Algar. Il y a tellement de choses à explorer là-bas !', 56647),
(275557, 'frFR', '', 'Grim Batol n\’a pas vraiment été tendre avec le peuple dragon, alors je tente de ne pas trop y penser.\n\nMais si vous comptez vous y rendre pour vaincre de terribles adversaires et vous emparer de leurs trésors, là, j\’ai hâte d\’en entendre parler.\n\nEmpruntez le portail des voies temporelles vers les hautes-terres du Crépuscule, puis dirigez-vous vers l\’ouest pour trouver l\’entrée nichée dans le flanc de la montagne.', 56647),
(275556, 'frFR', '', 'Bien entendu, pour celui-ci, vous irez à Boralus. Regardez le long des quais, sous le marché des Alizés.\n\nSauf si vous appartenez à la Horde. Dans ce cas, vous trouverez une entrée beaucoup plus sûre au port des Rapines.\n\nCommencez par emprunter le portail des voies temporelles pour la rade de Tiragarde, puis dirigez-vous vers le nord vers n\’importe quelle ville où l\’on n\’essaiera pas de vous tuer à vue.', 56647),
(275555, 'frFR', '', '« Sillage » est un terme curieux. Il désigne ce qu\’on laisse derrière soi après son passage, et s\’applique aussi bien à des personnes qu\’à des véhicules ou même des odeurs.\n\n<Lindormi fait une courte pause pour observer votre réaction>\n\nQuoi qu\’il en soit, prenez le portail des voies temporelles vers le Bastion et dirigez-vous vers le sud-ouest. Cherchez l\’entrée dans la partie du temple du Courage qui n\’a pas été complètement détruite.', 56647),
(275554, 'frFR', '', 'Tirna Scithe est un endroit idéal pour se perdre. Vous pouvez même vous perdre en route !\n\nPrenez le portail des voies temporelles pour Sylvarden, puis dirigez-vous vers l\’ouest et cherchez l\’entrée très bien cachée au milieu des racines.', 56647),
(269791, 'frFR', '« … sur des ailes crépitantes. »', '', 56647),
(269790, 'frFR', '', '« … sur des ailes crépitantes. »', 56647),
(268067, 'frFR', 'Vous arrivez à y croire, $n ? Pensez à toute l\’histoire qui est enterrée ici !', '', 56647),
(266394, 'frFR', 'Si l\’$uinconnu:inconnue; est capable de se battre ainsi, nous devons pouvoir faire de même. L\’empereur exige que nous dépassions les limites de nos adversaires.', '', 56647),
(266392, 'frFR', 'Nous sommes nourris par la Flamme sacrée, mon frère. Laissons les impies subir la fureur des Kobyss. Nous en profiterons pour les prendre en tenaille.', '', 56647),
(266390, 'frFR', 'Excusez Sybaestan, $ucher ami:chère amie;. Sans votre aide, nous n\’en serions pas là.', 'Excusez Sybaestan, $ucher ami:chère amie;. Sans votre aide, nous n\’en serions pas là.', 56647),
(266389, 'frFR', 'Votre discipline au combat est impressionnante, mon frère. L\’$uinconnu:inconnue; ferait bien d\’en prendre de la graine.', '', 56647),
(261758, 'frFR', '<Anduin se tourne vers vous.>\n\n$nVous avez été très utile, comme toujours. Comment faites-vous ?\n\nDepuis l\’Ombreterre, je…\n\nJ\’ai du mal.', '', 56647),
(261247, 'frFR', '<Anduin se tourne vers vous.>\n\nVous avez été très utile, $n, comme toujours. Comment faites-vous ?\n\nComment pouvez-vous me regarder, après ce qui s\’est passé ? Après ce que je vous ai fait ?\n\nJ\’ai tenté de vous tuer.', '', 56647),
(260534, 'frFR', 'Mais, quand ?', '', 56647),
(260468, 'frFR', 'Depuis quand existe Dornogal ?', '', 56647),
(260045, 'frFR', 'Comment ?', '', 56647),
(259965, 'frFR', 'Ah ! Il est temps de s\’y remettre… ou pas.', '', 56647),
(258826, 'frFR', 'Bien le bonjour ! Une chasse au trésor, ça vous tente ? Eh oui, je m\’en doutais.\n\nJ\’ai une liste d\’objets que j\’ai perdus… euh, je veux dire, d\’objets parfaitement aléatoires se trouvant dans cette grotte ! La première personne qui me les rapporte gagnera ce trésor ?\n\nTenez, je vous mets aussi ce cristal qui permet de nager plus vite. C\’est l\’affaire du siècle !', '', 56647),
(258555, 'frFR', '', '<Vokgret boit une gorgée de sa Brassecendre, puis lève les yeux vers vous.>\n\nTrouver votre opale liquide va me prendre du temps, ma petite pierre précieuse.\n\nAlors pendant que mes taupes passent le marché au peigne fin, j\’apprécierais beaucoup que vous mettiez votre ingéniosité à profit.', 56647),
(256097, 'frFR', '', 'Salutations ! Enchantée de faire votre connaissance !\n\nJe me nomme Tharessa. C\’est Rannan qui m\’envoie. Je suis la nouvelle recrue de l\’Expédition algarie. C\’est un plaisir d\’être ici.\n\nMême si… enfin, vous savez.\n\nJe suis férue de technologie des Titans. Rannan et Tuberros sont assez calés dans ces « machins », comme dirait Rannan. J\’ai hâte de voir ça de plus près !\n\nOn dirait bien que je vais y parvenir ! Même si cela a nécessité un atterrissage d\’urgence en ville…', 56647),
(266645, 'frFR', 'Brann ? Il doit se trouver quelque part avec les autres.\n\nIl faut y aller, $uchampion:championne;. J\’entends les plaies d\’Azeroth appeler à l\’aide.', '', 56647),
(266491, 'frFR', '', 'Vous $ubon ami:bonne amie; des Kobolds, $n. Merci.', 56647),
(254492, 'frFR', 'Comment ça va ?', 'Comment ça va ?', 56647),
(252740, 'frFR', 'Restez vigilants. Personne ne doit perturber la Sublimation.', 'Restez sur vos gardes. Personne ne doit perturber la Sublimation.', 56647),
(251935, 'frFR', 'Parlons peu. L\’air est infesté de poison.\n\nPrenez ces chaussures piétinantes. Utilisez-les pour réparer les purificateurs d\’airs cassés et pour récupérer les engrenages après avoir tué les Kobolds. Sécurisez tous les engrenages, sauvez le moulin à eau.\n\nAllez-y.', '', 56647),
(261702, 'frFR', '', 'Le moment est venu de découvrir qui nous sommes.', 56647),
(261700, 'frFR', '', 'Azeroth grandit, nous devons en faire autant.', 56647),
(261701, 'frFR', '', 'Nous devons accepter le changement.', 56647),
(261699, 'frFR', '', 'Les traditions stagnantes ont failli avoir raison de nous.', 56647),
(261696, 'frFR', '', 'Avant le sacrifice de Magni, les Terrestres se bornaient à leur rôle intrinsèque.', 56647),
(252793, 'frFR', 'The Weaver bids you welcome.', 'La Tisserande vous souhaite la bienvenue.', 56647),
(252791, 'frFR', 'Scurry on, little scarab!', 'Détale, petit scarabée !', 56647),
(256695, 'frFR', '', 'Pour couvrir votre propre traîtrise, je parie ! Une fois sa tête tombée, c\’est la vôtre que je prendrai.', 56647),
(256694, 'frFR', 'J\’écraserai toute insurrection au nom de la reine Ansurek.', '', 56647),
(256691, 'frFR', 'La seule chose que vous dévoilerez sera votre faiblesse.', '', 56647),
(256690, 'frFR', '', 'Les conspirateurs sont là ! Quand je les aurai tués, je trouverai le traître parmi nous.', 56647),
(266867, 'frFR', 'Si vous trouvez quelque chose, emportez-le loin d\’ici. Moi, je m\’en lave les griffes.', 'Si vous trouvez quelque chose, emportez-le loin d\’ici. Moi, je m\’en lave les griffes.', 56647),
(260896, 'frFR', '', 'Ombre perforante.', 56647),
(260892, 'frFR', '', 'Vortex gluant.', 56647),
(260891, 'frFR', '', 'Détonation visqueuse.', 56647),
(260875, 'frFR', '', 'Inutile de lutter.', 56647),
(260874, 'frFR', '', 'Dans mes filets.', 56647),
(260838, 'frFR', 'L\’essaim a faim.', '', 56647),
(260837, 'frFR', 'Saccager.', '', 56647),
(260836, 'frFR', 'Assaut.', '', 56647),
(260835, 'frFR', 'Carnage fulgurant.', '', 56647),
(260834, 'frFR', 'Irrésistible.', '', 56647),
(260822, 'frFR', '', 'Vos vies sont perdues !', 56647),
(260821, 'frFR', 'Vos crânes m\’appartiennent !', '', 56647),
(261912, 'frFR', 'Au sol, ma troupe !', '', 56647),
(254365, 'frFR', '', 'Quand Dagran s\’intéresse à quelque chose, inutile d\’essayer de l\’en décourager, on dirait.\n\nComme je vous le disais, Taelloch est un avant-poste minier de première importance, qui a toujours fonctionné comme une machine bien huilée. Je connais bien Kol Bruncrag, le contremaître, mais nous n\’avons pas parlé depuis un moment.\n\nJe dois comprendre pourquoi la production de minerai a cessé, même si le haut-mandataire préférerait que je m\’en abstienne. Il a sans doute envoyé ses propres enquêteurs, mais nous devrions voir par nous-mêmes.', 56647),
(271002, 'frFR', 'Les Terrestres à la surface du secteur AR-938 ont récemment subi des déboires.\n\nAprès l\’arrivée brutale des gens venus de contrées lointaines sur leurs côtes, leur forteresse, Dornogal, fut prise d\’assaut par des Nérubiens. Les gens venus d\’ailleurs et les chevaucheurs et chevaucheuses de tempête parvinrent à repousser ces assaillants, mais la galerie Primaire fut gravement endommagée.\n\nAvec l\’aide des gens du dehors, les groupes de Terrestres surnommés les êtres déliés (autrefois les « êtres liés à la pierre ») et les êtres assermentés (restés fidèles aux Titans) s\’unirent pour défendre la surface, repousser les Nérubiens et restaurer la galerie Primaire.\n\nAu cours de ces évènements, les chevaucheurs et chevaucheuses de tempête essuyèrent de lourdes pertes, dont celle du garde-tempête Baelgrim. Toutefois, l\’accès de la galerie Primaire à Gundargaz et aux mandataires des machines fut rétabli.\n\nLa galerie Primaire est toujours en réparation.', '', 56647),
(270198, 'frFR', 'La bête de somme de la Transformacie sent vos phéromones et s\’éloigne de vous.', '', 56647),
(266936, 'frFR', '', 'Juste que vous me faites penser à Turalyon : courageux au combat, mais timide en amour.', 56647),
(265279, 'frFR', 'La bataille est sur le point de tourner !', '', 56647),
(265155, 'frFR', '', 'Votre survie n\’était pas nécessaire.', 56647),
(263196, 'frFR', '', 'Nous n\’avons jamais connu d\’autre règne que celui du haut-mandataire… mais il n\’est plus l\’un des nôtres.', 56647),
(262604, 'frFR', '', 'Protocole sismique activé.', 56647),
(262333, 'frFR', 'Je parie qu\’on peut rebondir sur ces petits champignons.', '', 56647),
(261918, 'frFR', '', 'Indésirables ? Vous nous avez vus tomber du ciel et combattre pour survivre !', 56647),
(259785, 'frFR', 'Maintenant, débarrassons-nous de ce truc. On dirait que les Kobyss l\’ont attiré ici avec cet appât devant.', '', 56647),
(259762, 'frFR', '', 'Abandonnez-vous à la nuit.', 56647),
(256027, 'frFR', '', 'Vous avez ignoré votre soigneur, encore et encore ! Comment vouliez-vous que je résiste à en profiter ?', 56647),
(256024, 'frFR', 'Moi qui cherchais un moyen de faire avancer mon fantassin sans le perdre ! Alors, Faerin, on laisse son cavalier exposé ? C\’est risqué.', '', 56647),
(255118, 'frFR', 'Cette ville est fascinante. C\’est incroyable de voir ce que le peuple arathi a réussi à construire ici en si peu de temps.\n\nDire que pendant ce temps, nous avons affronté la Légion. Puis, il y a eu la Quatrième guerre, puis…\n\nEnfin, quel spectacle !', '', 56647),
(254822, 'frFR', 'C\’est une bonne question, $r. Je suis un Éveilleur. Il est de mon devoir de visiter ces anciens lieux, ou celles et ceux qui viennent de s\’éveiller, et de m\’assurer que tout est en ordre. Considérez les abîmes Retentissants comme un géant endormi. Je m\’assure qu\’on en prenne bien soin !\n\nProtégez-moi pendant que je me consacre à mon rituel, et essayez d\’absorber le maximum d\’énergie naissante de la Machine ! Si nous parvenons à nous recharger suffisamment, nous devrions pouvoir tenir le coup…', '', 56647),
(268527, 'frFR', 'Vous n\’êtes pas la seule, prélate. Voir le visage de Beledar dans cet état est présage de malheur et de discorde.', '', 56647),
(267619, 'frFR', 'Et j\’y laisserai toutes les pièces d\’armure de mailles que je trouverai pour toi et Kralla, Bleue.', '', 56647),
(266121, 'frFR', '<Dagran se lance dans une longue explication au sujet de la cire des Kobolds, de ses tenants et de ses aboutissants. De toute évidence, il s\’agit du résultat de recherches qu\’il a menées à Forgefer et en Khaz Algar, et non d\’une quelconque expérience concrète.>', '', 56647),
(265612, 'frFR', 'J\’ai entendu des histoires sur ce peuple arathi. Quand j\’étais roi… Heu, j\’étais curieux.', '', 56647),
(265403, 'frFR', 'Qu\’essayez-vous de nous dire ?', '', 56647),
(265214, 'frFR', 'C\’est fascinant…', '', 56647),
(264962, 'frFR', 'Si c\’est vrai, je veux le voir de mes propres yeux. Ces personnes pourraient s\’avérer utiles dans notre combat contre Xal\’atath.', '', 56647),
(264692, 'frFR', '$n ! J\’ai réussi à libérer quelques cendrabeilles !', '', 56647),
(264131, 'frFR', 'Tout le monde a l\’air à cran, vous ne trouvez pas ? Je me demande pourquoi.\n\nOh, mais bien sûr. C\’est à cause des horribles visions de destruction. C\’est pour ça que tout Dalaran se téléporte en Khaz Algar. Ça me revient.', '', 56647),
(264128, 'frFR', 'Vous redoutez les dangers présents en Khaz Algar ? Ça ne sert à rien. Après tout, l\’incroyable Reno Jackson est là pour vous protéger !', '', 56647),
(264108, 'frFR', 'Quoi qu\’il en soit, disposer de Xal\’atath ne suffira pas à sauver notre peuple. C\’est Ansurek qui nous mène à notre perte.', '', 56647),
(262984, 'frFR', 'Votre arrivée m\’a été annoncée par la messagère…', '', 56647),
(262611, 'frFR', '', 'Extinction… des… des… des… des systèmes…', 56647),
(261944, 'frFR', 'C\’est impossible. Il faut que ce soit moi. Et vous, vous devez guider les Terrestres.', '', 56647),
(261934, 'frFR', 'J\’ai entendu de nombreuses histoires sur leur bravoure… C\’est un signe… Un signe des Titans !', '', 56647),
(261921, 'frFR', 'Vos besoins n\’ont pas d\’importance.', '', 56647),
(261418, 'frFR', '', 'Hem hem ! Je disais donc… nous voilà occis !', 56647),
(261128, 'frFR', '', 'Le haut-élévateur Etak\’kaht, le magistrat de Haut-Creux, pourra jouer de son influence pour m\’accorder la sublimation.\n\nEn supposant que je gagne sa faveur.\n\n<Tous les yeux de Tx\’itk se plissent sous l\’effet d\’une légère frustration.>\n\n… En supposant que nous le trouvions.', 56647),
(260471, 'frFR', 'Vous n\’avez pas une estimation ?', '', 56647),
(260469, 'frFR', '', 'Réponse inconnue. Nos archives devraient contenir ces informations, mais comme je l\’ai dit, elles sont hors service.', 56647),
(260334, 'frFR', 'J\’ai observé les cristaux de leurs flammeclés. Ce n\’est pas de l\’azérite, mais c\’est assez proche. Il doit y avoir un lien.', '', 56647),
(260299, 'frFR', '', 'Tout le monde a une histoire comme ça. Je me souviens d\’une fois où j\’étais dans une grotte avec…', 56647),
(260176, 'frFR', 'Ah ha ! Bien sûr ! Vos souvenirs sont sans doute comme les miens. Un peu troubles au bout de quelques milliers d\’années…', '', 56647),
(260092, 'frFR', '', 'Je prélèverai vos têtes quand elles vaudront quelque chose… d\’ici là… Soyez sur vos gardes.', 56647),
(260028, 'frFR', 'Désormais, je vais de l\’avant. Une nouvelle aventure nous attend.', '', 56647),
(260019, 'frFR', '', 'Maintenant que tu es… différent, comment… comment ça va ?', 56647),
(259046, 'frFR', 'Vous aventurez pas dans la nuit, hein !', 'Ne vous aventurez pas dans la nuit.', 56647),
(258553, 'frFR', '<Le tisse-rat tient la note pendant que vous l\’examinez.>\n\nPlusieurs expériences ratées sèment le chaos dans le donjon de l\’Abîme. Détruisez-les avant qu\’elles ne s\’enfuient.\n\nVous pouvez utiliser les explosifs aux phéromones qui sont cachés dans les environs pour les arrêter. Mais tout d\’abord, vous devez masquer votre odeur. Les phéromones que je vous ai offertes feront l\’affaire.\n\nRécupérez les appareils et éliminez ces pauvres créatures.\n\n– La Tisserande', '', 56647),
(258479, 'frFR', 'Ah ! Ouais ! Fuir !', 'Ouais ! Fuir !', 56647),
(258194, 'frFR', 'Allez, tout le monde ! Reprenez le travail !', '', 56647),
(258037, 'frFR', 'Ne vous méprenez pas. Nous devons nous rendre en Khaz Algar sans délai. Mais je suis encore fatigué.\n\nAzeroth requiert pas mal d\’effort quand elle veut.', '', 56647),
(258035, 'frFR', 'Ainsi, notre destin nous attend en Khaz Algar. Que trouverons-nous là-bas ? Outre de la fumée et des flammes, bien sûr.', '', 56647),
(258010, 'frFR', 'Grand-père a connu pire. Je sais qu\’il va bientôt se réveiller. \n\nIl le faut…', '', 56647),
(258006, 'frFR', 'Azeroth n\’est pas responsable de cet évènement. Magni connaissait les risques lorsqu\’il a voulu se lier à elle malgré les réticences de son cœur.\n\nEt maintenant, espérons qu\’il a pu entendre son message.', '', 56647),
(257697, 'frFR', 'Ils se sont téléportés ? Enfin, on avance !', 'Ils se sont téléportés ? Enfin, on avance !', 56647),
(257511, 'frFR', '', 'Olbarig, où êtes-vous ? Nous avons besoin de vous…', 56647),
(255510, 'frFR', '', 'Attendez ! Nous ne savons pas ce qui nous attend ! Les renforts arrivent, nous pourrions…', 56647),
(254629, 'frFR', '', 'Ces… ombres ! C\’est trop… Argh !', 56647),
(253162, 'frFR', 'Nous ne pouvons inviter personne d\’autre.', '', 56647),
(253151, 'frFR', 'J\’ai pas assez de fureur.', '', 56647),
(252126, 'frFR', 'Quelle joie de voir que grand-père va bien ! Nous n\’avons pas passé beaucoup de temps ensemble, et le savoir…\n\nMais tout est rentré dans l\’ordre ! Il a l\’air d\’être complètement rétabli.', '', 56647),
(268542, 'frFR', '', 'Gemmes mémorielles obtenues. Mais nous devons continuer pour éradiquer la menace nérubienne dans cette zone. Toutefois, le nombre de toiles est impressionnant…\n\nJe vais modifier l\’appareil pour pouvoir détruire les toiles avec. Utilisez-le pour dégager la voie.', 56647),
(268257, 'frFR', 'C\’est la faute de Trempe ! Il a été trop lent.', '', 56647),
(268256, 'frFR', 'Ils ont sali ta robe parce que tu as tiré avant que le tank ne soit prêt.', '', 56647),
(268043, 'frFR', '', 'Ma sœur ? Tout va bien ?', 56647),
(267317, 'frFR', '', '<Tara semble avoir oublié sa timidité et elle agite à présent sa cuillère avec force enthousiasme, comme s\’il s\’agissait d\’une épée.>\n\nQuand je serai grande, je veux être une Terrestre ! Maman, elle dit que les Terrestres ils sont tout en cailloux et qu\’ils ont des gemmes dedans.\n\nUn jour, j\’ai voulu manger une gemme, mais c\’était dur, alors j\’ai décidé de commencer par les broyer pour que ce soit plus facile à avaler !', 56647),
(265656, 'frFR', '', 'Il… s\’agit d\’une faveur qu\’un chevalier m\’a demandée avant de partir en expédition.', 56647),
(265652, 'frFR', 'Ce dessin représente la légende de Griffe de feu. Un lynx de guerre légendaire qui a bravé un navire en flammes pour sauver son cavalier.', '', 56647),
(265609, 'frFR', '', 'Heureuse de vous voir. J\’ai suivi celui-ci depuis qu\’il est sorti de son trou.', 56647),
(265317, 'frFR', 'Ouah, elle a dit que j\’étais un génie ? Ce genre de choses me permet d\’allumer ma propre lampe, si vous me permettez l\’expression.', '', 56647),
(264561, 'frFR', '', 'La créature a regagné sa reine. Nul doute qu\’elle lui racontera votre formidable héroïsme.', 56647),
(264549, 'frFR', '', 'Par chance, ma fille et ses enfants sont sains et saufs. Vous avez affaibli le commandant et nettoyé ma maison. Merci.', 56647),
(262945, 'frFR', 'Nous avons entrepris la traversée des mers déchaînées. Jamais auparavant, je n\’avais vu de vagues aussi hautes ou de vents aussi violents ! À de nombreuses reprises, j\’ai cru que nos aéronefs allaient sombrer dans la tempête !', 'Nous avons entrepris la traversée des mers déchaînées. Jamais auparavant, je n\’avais vu de vagues aussi hautes ou de vents aussi violents ! À de nombreuses reprises, j\’ai cru que nos aéronefs allaient sombrer dans la tempête !', 56647),
(262812, 'frFR', 'Entrez !', 'Entrez !', 56647),
(262440, 'frFR', 'Ça va chauffer !', '', 56647),
(262197, 'frFR', 'Il y a plus appétissant comme repas, mais si vous en capturez quelques-uns et que vous les enfermez dans une jarre, vous aurez une excellente source de lumière.\n\nUn jour, je fouillais au milieu des herbes quand un gros lumiptère a été attiré par la lumière de ma jarre ! Il m\’a suivi un moment, comme un animal de compagnie. Cette gentille bête voulait simplement bourdonner en produisant sa lumière colorée.', '', 56647),
(261385, 'frFR', 'La marionnette de Terrestre est figée dans un état de désespoir et représente dans les moindres détails les véritables Terrestres qui ont croisé votre route plus haut.\n\nLa texture de pierre de cette création est identique à celle des authentiques Terrestres.', 'La marionnette de Terrestre est figée dans un état de désespoir et représente dans les moindres détails les véritables Terrestres qui ont croisé votre route plus haut.\n\nLa texture de pierre de cette création est identique à celle des authentiques Terrestres.', 56647),
(261292, 'frFR', 'Ne restez pas là !', '', 56647),
(260817, 'frFR', 'Bienvenue, $r.\n\nIl y a bien longtemps, le conseiller Merrix m\’a nommé décorateur de Dornogal.\n\nIl est de mon devoir de maintenir l\’harmonie esthétique de notre ville. À chaque cycle qui passe, je façonne avec diligence le style et la beauté des rues de Dornogal, les imprégnant d\’une élégance subtile et d\’une allure fonctionnelle qui conviennent à notre héritage.\n\nEn tant que décorateur attitré, je m\’engage à préserver l\’héritage de Merrix et à veiller à ce que Dornogal reste un symbole de beauté et d\’émerveillement pour les cycles à venir.\n\nComment puis-je vous aider ?', '', 56647),
(259422, 'frFR', '', 'Merci ! Prenez ces bottes et montrez aux Kobyss qu\’on ne va pas les regarder attaquer nos villages sans rien faire.', 56647),
(259414, 'frFR', '', 'Quand un groupe de Kobyss s\’est enfui après avoir attaqué un village et volé ses reliques, je l\’ai poursuivi jusque dans le Puisard.\n\nMalheureusement, je me spécialise plus dans les inventions que dans le combat. C\’est juste l\’adrénaline qui m\’a fait parvenir jusqu\’ici. J\’ai toutefois une invention qui pourra vous être utile.\n\nVous pouvez utiliser mes bottes légères. Leur magie vous permettra de vous lancer haut dans les airs pour fondre sur vos adversaires lorsqu\’ils s\’y attendront le moins. Elles devraient vous aider à venir à bout des Kobyss plus bas.', 56647),
(257935, 'frFR', '', 'Les Nérubiens se servent de Skardyns pour capturer les mandataires des machines.\n\nVoici le plan : vous allez prendre cet appareil. Il attirera les Skardyns ailleurs. Vous vous en servirez pour sauver les autres mandataires. \n\nCe plan est… expérimental. Il ne me convient pas. Je resterai ici.', 56647),
(256314, 'frFR', '', 'Les lynx impériaux peuvent se montrer terriblement têtus. Stincel ne laisse personne d\’autre que moi le monter. Et s\’il est de mauvais poil, je dois finir mes livraisons à pied.\n\nMais quand il est dans ses bons jours, il file comme le vent. Et je ne laisserais personne d\’autre que lui me couvrir sur ces routes.', 56647),
(255997, 'frFR', 'Voilà un voyage qui s\’annoncerait intéressant.', '', 56647),
(255898, 'frFR', '<Kiera fredonne en cuisinant, un sourire aux lèvres. Un fumet d\’oignon et d\’ail flotte dans l\’air.>', '<Kiera fredonne en cuisinant, un sourire aux lèvres. Un fumet d\’oignon et d\’ail flotte dans l\’air.>', 56647),
(253535, 'frFR', '', 'Par les cendres, envolée. Celle qui est venue à notre secours n\’aime pas les Nérubiens. Cherchez là. J\’emmène les autres à l\’abri.', 56647),
(248952, 'frFR', 'On dirait qu\’on va devoir sauter !', '', 56647);
INSERT INTO `char_titles_locale` (`ID`, `locale`, `Name_lang`, `Name1_lang`, `VerifiedBuild`) VALUES
(656, 'frFR', '%s l\’Éternel', '%s l\’Éternelle', 56647),
(854, 'frFR', '%s, le Trempé', '%s, la Trempée', 56647),
(822, 'frFR', '%s, le héros trempé', '%s, l\’héroïne trempée', 56647);
INSERT INTO `chr_classes_locale` (`ID`, `locale`, `Name_lang`, `NameMale_lang`, `NameFemale_lang`, `Description_lang`, `RoleInfoString_lang`, `DisabledString_lang`, `HyphenatedNameMale_lang`, `HyphenatedNameFemale_lang`, `VerifiedBuild`) VALUES
(4, 'frFR', 'Voleur', 'Voleur', 'Voleuse', 'Les voleurs endossent souvent le rôle d\’assassin ou d\’éclaireur, mais nombre d\’entre eux sont des loups solitaires. Ils peuvent se déplacer furtivement autour de leurs ennemis ou attaquer un adversaire dans le dos pour tenter de l\’achever rapidement.', 'Rôle : |cffffffffinfliger des dégâts en mêlée|r', 'Vous devez choisir une race compatible avec cette classe.', 'Voleur', 'Voleuse', 56647);
INSERT INTO `chr_customization_choice_locale` (`ID`, `locale`, `Name_lang`, `VerifiedBuild`) VALUES
(56557, 'frFR', 'Naturelle', 56647),
(56974, 'frFR', 'Échappement', 56647);
INSERT INTO `chr_customization_option_locale` (`ID`, `locale`, `Name_lang`, `VerifiedBuild`) VALUES
(8855, 'frFR', 'Transformation complète', 56647),
(8805, 'frFR', 'Queue', 56647),
(8804, 'frFR', 'Ailes', 56647),
(8803, 'frFR', 'Nez', 56647),
