INSERT INTO `chr_races_locale` (`ID`, `locale`, `Name_lang`, `NameFemale_lang`, `NameLowercase_lang`, `NameFemaleLowercase_lang`, `LoreName_lang`, `LoreNameFemale_lang`, `LoreNameLower_lang`, `LoreNameLowerFemale_lang`, `LoreDescription_lang`, `ShortName_lang`, `ShortNameFemale_lang`, `ShortNameLower_lang`, `ShortNameLowerFemale_lang`, `VerifiedBuild`) VALUES
(85, 'frFR', 'Terrestre', 'Terrestre', 'terrestre', 'terrestre', 'Terrestre', '', 'terrestre', '', 'Tout juste libéré des décrets qui l\’entravaient, le nouveau peuple terrestre fait preuve d\’une curiosité sans bornes pour explorer le monde et rejoindre l\’Alliance.', 'Terrestre', '', 'terrestre', '', 56647),
(84, 'frFR', 'Terrestre', 'Terrestre', 'terrestre', 'terrestre', 'Terrestre', '', 'terrestre', '', 'Tout juste libéré des décrets qui l\’entravaient, le nouveau peuple terrestre fait preuve d\’une curiosité sans bornes pour explorer le monde et rejoindre la Horde.', 'Terrestre', '', 'terrestre', '', 56647),
(36, 'frFR', 'Orc mag\’har', 'Orque mag\’har', 'orc', 'orque', 'Mag\’har', '', 'Mag\’har', '', 'Autrefois divisés en clans rivaux, les Orcs de Draenor épargnés par la corruption sont à présent réunis sous la bannière des féroces Mag\’har.', 'Orc', '', 'Orc', '', 56647);
