INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'frFR', 'Brann Barbe-de-Bronze', 'Compagnie de Gouffre digne de confiance', 56647),
(2600, 'frFR', 'Les Fils tranchés', 'Le règne tumultueux de la reine Ansurek a connu quelques détracteurs. Les Fils tranchés ont œuvré avec intelligence et discrétion pour saboter le règne d\’Ansurek de l\’intérieur.', 56647),
(2596, 'frFR', 'Les Fils tranchés (parangon)', 'Le règne tumultueux de la reine Ansurek a connu quelques détracteurs. Les Fils tranchés ont œuvré avec intelligence et discrétion pour saboter le règne d\’Ansurek de l\’intérieur.', 56647),
(2606, 'frFR', 'Haut-Creux', 'Contrôle le comportement des créatures à Haut-Creux de la cité des Fils.', 56647),
(2649, 'frFR', 'Le général (parangon)', 'Autrefois le plus illustre chef militaire d\’Azj-Kahet, Anub\’azal a dû laisser sa place à l\’un des Transcendés si chers au cœur d\’Ansurek. Une décision qui ne restera pas sans conséquences.', 56647),
(2648, 'frFR', 'La Tisserande (parangon)', 'Autrefois tisserande royale, la veuve Arak\’nai pose désormais un regard critique sur son ancien foyer. Grâce à son réseau de tisse-rats et d\’espions, peu de choses lui échappent.', 56647),
(2647, 'frFR', 'Le vizir (parangon)', 'Occupant la position la plus dangereuse de toutes, l\’exécuteur Nizrek passe ses journées à conseiller la reine Ansurek. Fort heureusement, Ansurek ignore qu\’il passe le reste de son temps à essayer de mettre fin à son règne.', 56647),
(2607, 'frFR', 'Le vizir', 'Occupant la position la plus dangereuse de toutes, l\’exécuteur Nizrek passe ses journées à conseiller la reine Ansurek. Fort heureusement, Ansurek ignore qu\’il passe le reste de son temps à essayer de mettre fin à son règne.', 56647),
(2605, 'frFR', 'Le général', 'Autrefois le plus illustre chef militaire d\’Azj-Kahet, Anub\’azal a dû laisser sa place à l\’un des Transcendés si chers au cœur d\’Ansurek. Une décision qui ne restera pas sans conséquences.', 56647),
(2601, 'frFR', 'La Tisserande', 'Autrefois tisserande royale, la veuve Arak\’nai pose désormais un regard critique sur son ancien foyer. Grâce à son réseau de tisse-rats et d\’espions, peu de choses lui échappent.', 56647);
