INSERT INTO `mail_template_locale` (`ID`, `locale`, `Body_lang`, `VerifiedBuild`) VALUES
(632, 'frFR', 'Ça fait dix ans qu\’on joue à Hearthstone, c\’est à peine croyable.\n\nJ\’organise des parties, nous vous y attendons !', 56647),
(619, 'frFR', 'Hearthstone fête ses 10 ans, c\’est à peine croyable !\n\nJ\’organise des parties, nous vous y attendons !', 56647),
(628, 'frFR', 'Nous avons récupéré quelque chose que vous aviez obtenu pendant votre service dans le Cours du temps, et décidé que cet objet pouvait persister sans perturber la ligne temporelle. Vous le trouverez en pièce jointe.\n\nÀ très bientôt.\n\n   – Moratari', 56647);
