INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(776, 'frFR', 'Rylak spectral rapide', '|cFFFFD200Héritage|r', 'Même les morts ont besoin de faire un tour, de temps à autre.', 56647),
(2188, 'frFR', 'Kah, légende des profondeurs', '|cFFFFD200Haut fait : |rLe concours effréné|n|cFFFFD200Catégorie : |rPêche', '', 56647),
(2218, 'frFR', 'Gangroptère du gladiateur forgé', '|cFFFFD200Haut fait :|r gladiateur, saison 1 de The War Within|n|cFFFFD200Catégorie :|r JcJ', 'Après un éveil dans les cavernes au milieu d\’un champ de bataille, votre armure vous prépare à tout.', 56647),
(2159, 'frFR', 'Unité de défense mécanique 1-11', '|cFFFFD200Trésor :|r cache éveillée|n|cFFFFD200Région :|r abîmes Retentissants', 'L\’une des nombreuses mécarmures conçues pour garder la Machine. Après des années de service, elle n\’est plus apte au combat. Elle reste cependant un moyen de transport impressionnant.', 56647),
(2209, 'frFR', 'Nez-de-boue cramoisie', '|cFFFFD200Vendeur :|r Cireur Squick|n|cFFFFD200Région : |rLes abîmes Retentissants|n|cFFFFD200Coût : |r8 125|Hcurrency:2815|h|TInterface\\ICONS\\SPELL_AZERITE_ESSENCE14.BLP:0|t|h', 'Fréquemment utilisées comme montures par les Kobolds, les Nez-de-boue vous sont à présent proposées par l\’Assemblée des profondeurs.', 56647);
